# --- merge ---------------------------------------------------------------------------------

if wanted merge; then
    case_ "merge: clean three-way" fx_branches ':' 'G merge feat'
    case_ "merge: -m message" fx_branches ':' 'G merge -m "custom message" feat'
    case_ "merge: -m twice" fx_branches ':' 'G merge -m one -m two feat'
    case_ "merge: -F file" fx_branches 'printf "from file\n\nbody\n" > /tmp/1git-merge-msg.txt' 'G merge -F /tmp/1git-merge-msg.txt feat'
    case_ "merge: --no-ff on a fast-forward" fx_base 'git switch -q side; git merge -q main 2>/dev/null; git reset -q --hard main~1' 'G merge --no-ff main'
    case_ "merge: fast-forward" fx_base 'git switch -q side' 'G merge main'
    case_ "merge: --ff-only possible" fx_base 'git switch -q side' 'G merge --ff-only main'
    case_ "merge: --ff-only not possible" fx_branches ':' 'G merge --ff-only feat'
    case_ "merge: --no-ff" fx_base 'git switch -q side' 'G merge --no-ff main'
    case_ "merge: --no-ff -m" fx_base 'git switch -q side' 'G merge --no-ff -m "no fast forward" main'
    case_ "merge: already up to date" fx_branches 'git merge -q feat' 'G merge feat; G merge HEAD'
    case_ "merge: up to date with --squash" fx_branches 'git merge -q feat' 'G merge --squash feat'
    case_ "merge: up to date with --no-ff" fx_branches 'git merge -q feat' 'G merge --no-ff feat'
    case_ "merge: --squash" fx_branches ':' 'G merge --squash feat'
    case_ "merge: --squash of a fast-forward" fx_base 'git switch -q side' 'G merge --squash main'
    case_ "merge: --squash then commit" fx_branches ':' 'G merge --squash feat; G commit -m squashed'
    case_ "merge: --squash with a conflict" fx_branches ':' 'G merge --squash clash'
    case_ "merge: --no-commit" fx_branches ':' 'G merge --no-commit feat'
    case_ "merge: --no-commit then commit" fx_branches ':' 'G merge --no-commit feat; G commit -m "by hand"'
    case_ "merge: --no-commit then commit with the default message" fx_branches ':' 'G merge --no-commit feat; GIT_EDITOR=true G commit'
    case_ "merge: --no-commit then --continue" fx_branches ':' 'G merge --no-commit feat; GIT_EDITOR=true G merge --continue'
    case_ "merge: --no-commit --no-ff" fx_base 'git switch -q side' 'G merge --no-commit --no-ff main'
    case_ "merge: --no-commit of a fast-forward" fx_base 'git switch -q side' 'G merge --no-commit main'
    case_ "merge: conflict" fx_branches ':' 'G merge clash'
    case_ "merge: conflict then abort" fx_branches 'git merge clash' 'G merge --abort'
    case_ "merge: conflict then quit" fx_branches 'git merge clash' 'G merge --quit'
    case_ "merge: conflict resolved then commit" fx_branches 'git merge clash; printf "R\n" > h.txt; git add h.txt' 'G commit -m resolved'
    case_ "merge: conflict resolved then --continue" fx_branches 'git merge clash; printf "R\n" > h.txt; git add h.txt' 'GIT_EDITOR=true G merge --continue'
    case_ "merge: --continue with unresolved paths" fx_branches 'git merge clash' 'GIT_EDITOR=true G merge --continue'
    case_ "merge: --abort with nothing to abort" fx_branches ':' 'G merge --abort; G merge --continue'
    case_ "merge: a second merge during a merge" fx_branches 'git merge clash' 'G merge feat'
    case_ "merge: conflict in two files" fx_conflict ':' 'G merge --abort; G merge other'
    case_ "merge: diff3 conflict style" fx_branches 'git config merge.conflictStyle diff3' 'G merge clash'
    case_ "merge: zdiff3 conflict style" fx_branches 'git config merge.conflictStyle zdiff3' 'G merge clash'
    case_ "merge: -X ours" fx_branches 'git checkout -q clash; echo "x" >> h.txt; git commit -qam "clash 2"; git checkout -q main' 'G merge -X ours clash'
    case_ "merge: -X theirs" fx_branches ':' 'G merge -X theirs clash'
    case_ "merge: -s ours" fx_branches ':' 'G merge -s ours clash'
    case_ "merge: -s ours up to date" fx_branches 'git merge -q feat' 'G merge -s ours feat'
    case_ "merge: unrelated histories" fx_branches 'git checkout -q --orphan unrelated; git rm -rfq .; echo u > u.txt; git add u.txt; git commit -qm unrelated; git checkout -q main' 'G merge unrelated'
    case_ "merge: unrelated histories allowed" fx_branches 'git checkout -q --orphan unrelated; git rm -rfq .; echo u > u.txt; git add u.txt; git commit -qm unrelated; git checkout -q main' 'G merge --allow-unrelated-histories unrelated'
    case_ "merge: dirty file in the way" fx_branches 'echo x >> g.txt' 'G merge feat; rm -f .git/AUTO_MERGE'
    case_ "merge: dirty file elsewhere is fine" fx_branches 'echo x >> h.txt; git stash -q; echo y > ignored.txt' 'G merge feat'
    case_ "merge: staged changes" fx_branches 'echo x >> g.txt; git add g.txt' 'G merge feat; rm -f .git/AUTO_MERGE'
    case_ "merge: untracked file in the way" fx_branches 'echo mine > n.txt' 'G merge feat'
    case_ "merge: a tag" fx_branches 'git tag v1 feat' 'G merge v1'
    case_ "merge: a remote-tracking name" fx_branches 'git update-ref refs/remotes/origin/feat feat' 'G merge origin/feat'
    case_ "merge: a commit id" fx_branches ':' 'G merge $(git rev-parse feat)'
    case_ "merge: not something we can merge" fx_branches ':' 'G merge nope'
    case_ "merge: no arguments" fx_branches ':' 'G merge'
    case_ "merge: on a topic branch names the destination" fx_branches 'git checkout -q -b topic' 'G merge feat'
    case_ "merge: detached HEAD" fx_branches 'git checkout -q --detach' 'G merge feat'
    case_ "merge: merging a merge commit" fx_mergecommit 'git checkout -q other' 'G merge main'
    case_ "merge: after a merge commit in history" fx_mergecommit 'git checkout -q other' 'G merge feat'
    case_ "merge: from a subdirectory" fx_branches 'mkdir sub' 'cd sub; G merge feat'
    case_ "merge: with merge.ff=false" fx_base 'git switch -q side; git config merge.ff false' 'G merge main'
    case_ "merge: with merge.ff=only" fx_branches 'git config merge.ff only' 'G merge feat'
    case_ "merge: -q" fx_branches ':' 'G merge -q feat'
    case_ "merge: editor with --edit" fx_branches ':' 'GIT_EDITOR="sed -i.bak 1s/^/EDIT:/" G merge --edit feat'
    case_ "merge: editor empties the message" fx_branches ':' 'GIT_EDITOR="cp /dev/null" G merge --edit feat'
    case_ "merge: --no-edit" fx_branches ':' 'GIT_EDITOR=false G merge --no-edit feat'
    case_ "merge: binary conflict" fx_branches 'git checkout -q feat; printf "\0a\n" > bin.dat; git add bin.dat; git commit -qm "feat bin"; git checkout -q main; printf "\0b\n" > bin.dat; git add bin.dat; git commit -qm "main bin"' 'G merge feat'
    case_ "merge: add/add conflict" fx_branches 'git checkout -q feat; echo F > both.txt; git add both.txt; git commit -qm "feat both"; git checkout -q main; echo M > both.txt; git add both.txt; git commit -qm "main both"' 'G merge feat'
    case_ "merge: modify/delete conflict" fx_branches 'git checkout -q feat; git rm -q h.txt; git commit -qm "feat rm h"; git checkout -q main' 'G merge feat'
    case_ "merge: delete/modify conflict" fx_branches 'git checkout -q feat; git rm -q h.txt; git commit -qm "feat rm h"' 'G merge main'
    case_ "merge: mode change" fx_branches 'git checkout -q feat; chmod +x g.txt; git commit -qam "feat chmod"; git checkout -q main' 'G merge feat'
    case_ "merge: file/directory conflict" fx_branches 'git checkout -q feat; git rm -q -r -f . ; mkdir dd; echo d > dd/x; git add dd; git commit -qm "feat dd"; git checkout -q main; git rm -q -f h.txt; echo file > dd; git add dd; git commit -qm "main dd file"' 'G merge feat'
    case_ "merge: criss-cross" fx_crisscross ':' 'G merge b'
    case_ "merge: criss-cross with a conflict" fx_crisscross 'git checkout -q a; echo conflict-a > f.txt; git commit -qam a-f; git checkout -q b; echo conflict-b > f.txt; git commit -qam b-f; git checkout -q a' 'G merge b'
    case_ "merge: criss-cross with diff3" fx_crisscross 'git config merge.conflictStyle diff3; git checkout -q a; echo conflict-a > f.txt; git commit -qam a-f; git checkout -q b; echo conflict-b > f.txt; git commit -qam b-f; git checkout -q a' 'G merge b'
fi
